      try {
        var r = await act('detect_pm');
        mgr = (((r.stdout || '') + '').trim().split('\\n')[0] || '').split('/').pop();
      } catch (e) { mgr = ''; }
      el('mgr').textContent = mgr ? ('package manager: ' + mgr) : 'no supported package manager found (apt/apk/dnf/yum)';
      return mgr;
