      + '<span class="text-xl font-semibold tabular-nums text-white" style="color:'+escf(col)+'">'+escf(label)+'</span>'
      + (sub ? '<span class="text-[10px] text-gray-400 mt-0.5">'+escf(sub)+'</span>' : '')
