    var rxHist = state.hist.netrx || [], txHist = state.hist.nettx || [], loadHist = state.hist.load || [];

    var cpuPct = m ? (m.cpu_pct != null ? m.cpu_pct : (m.cpu != null ? m.cpu : null)) : null;
