          html += '<div class="ks-card" data-ks-key="' + esc(String(p.host||p.host_port||i||'')) + '" style="display:flex;flex-direction:column;gap:12px">'
            // header
            + '<div style="display:flex;align-items:center;justify-content:space-between;gap:8px">'
